// Syscall number <-> name tables for x86_64 and aarch64 (generated by
// scripts/gen_syscall_table.py from the kernel UAPI headers and checked in,
// so the daemon has no build-time dependency on a particular kernel tree).
#pragma once

#include <optional>
#include <string_view>

namespace vessel::syscalls {

std::string_view name(int nr) noexcept;          // "" if unknown
std::optional<int> number(std::string_view name) noexcept;
int maxNr() noexcept;

enum class Category { kOther, kMemory, kFile, kNet, kProcess, kIpc, kTime };
Category categorize(int nr) noexcept;

}  // namespace vessel::syscalls
